/**
 * design_brief — the agent tool that turns a build brief into a complete,
 * LLM-authored visual design system.
 *
 * `loam_design` (src/tools/designExplore.ts) derives a handful of deterministic,
 * hue-based directions; it is excellent at producing a quick hero and a stable
 * fallback, but its palettes are generated by arithmetic rather than taste. This
 * tool is the opinionated, content-aware replacement for that deterministic
 * layer: it asks the model for one coherent visual system — a small semantic
 * palette, at most two typefaces, a layout plan, the imagery the page needs and
 * the accessibility rules the implementation must honour — validates the answer
 * against `DESIGN_BRIEF_JSON_SCHEMA`, and can persist the resulting token map so
 * the scaffold can write it straight into `globals.css`.
 *
 * Backward compatibility is preserved: `loam_design` keeps its deterministic
 * behaviour and its tests keep passing. `design_brief` is additive and only
 * changes the build flow when the caller reaches for it.
 *
 * Everything is offline-testable: the model client is injected, so a unit test
 * supplies a fake client and never calls a real external API.
 */

import type { OllamaClient } from "../ollama.js";
import {
  DESIGN_BRIEF_MAX_COLORS,
  DESIGN_BRIEF_MAX_FONTS,
  DESIGN_BRIEF_MIN_COLORS,
  generateDesignBrief,
  normalizeDesignBrief,
  writeDesignTokens,
  type DesignBrief,
} from "../design/brief.js";
import { bool, num, str, type Tool, type ToolContext, type ToolResult } from "./registry.js";

export const DESIGN_BRIEF_TOOL_NAME = "design_brief";
export const DESIGN_BRIEF_TOOL_NAMES = [DESIGN_BRIEF_TOOL_NAME];

/** Default workspace-relative path for the persisted token map. */
export const DESIGN_TOKENS_DEFAULT_PATH = "design-tokens.json";

export interface DesignBriefToolOptions {
  /** Injected model client; when omitted the tool degrades to the
   *  deterministic fallback so a run never blocks on design. */
  ollama?: OllamaClient;
}

function normalizeDirection(value: string): "ltr" | "rtl" | undefined {
  const v = value.trim().toLowerCase();
  if (v === "ltr" || v === "rtl") return v;
  return undefined;
}

/**
 * Shape the returned payload so the model always sees the brief, where it came
 * from, and — when asked — the workspace path of the persisted token map.
 */
export function formatDesignBriefResult(
  brief: DesignBrief,
  meta: { source: "model" | "fallback"; model: string; warnings: string[] },
  tokensPath?: string,
): string {
  return JSON.stringify({
    phase: "design-brief",
    source: meta.source,
    model: meta.model,
    warnings: meta.warnings,
    paletteSize: brief.palette.length,
    fontCount: brief.fonts.length,
    rtl: brief.rtl,
    ...(tokensPath ? { tokensPath } : {}),
    brief,
  });
}

export function createDesignBriefTools(options: DesignBriefToolOptions = {}): Tool[] {
  return [{
    name: DESIGN_BRIEF_TOOL_NAME,
    description:
      "Turn a short build brief into one complete, opinionated visual design system before writing any UI code. The model returns a semantic colour palette (3-5 named colours with roles and hex values), at most two typefaces with fallbacks, a mobile-first layout plan, the real imagery the page needs with alt text, and the accessibility rules to honour; the result is validated against a strict schema and can be written to a token file for globals.css. Use it at the start of any interface build: call design_brief first, keep the returned palette, fonts and layout consistent throughout the implementation, and reference the semantic tokens rather than raw colours. It replaces the deterministic hue palettes of loam_design for the visual system; keep loam_design for the hero image. When the model is unavailable it degrades to a curated deterministic brief so the build never stalls.",
    parameters: {
      type: "object",
      properties: {
        brief: {
          type: "string",
          description: "What is being built, for whom, and the mood it should carry — one or two sentences (e.g. 'A calm budgeting dashboard for freelancers, trustworthy and uncluttered').",
        },
        language: { type: "string", description: "Content language tag (e.g. 'en', 'ar'); Arabic content triggers RTL typography." },
        direction: { type: "string", enum: ["ltr", "rtl"], description: "Explicit text direction; overrides language inference." },
        audience: { type: "string", description: "Who will use the interface, to sharpen tone and hierarchy." },
        mood: { type: "string", description: "Desired feel (e.g. 'warm and crafted', 'technical and dense')." },
        constraints: { type: "string", description: "Hard constraints the design must respect (brand colours, existing tokens, no gradients)." },
        writeTokens: { type: "boolean", description: `Persist the token map to the workspace (default ${DESIGN_TOKENS_DEFAULT_PATH}). Default false.` },
        tokensPath: { type: "string", description: `Workspace-relative path for the token file (default ${DESIGN_TOKENS_DEFAULT_PATH}).` },
        maxAttempts: { type: "integer", minimum: 1, maximum: 4, description: "Model repair attempts before the deterministic fallback (default 2)." },
      },
      required: ["brief"],
    },
    async run(args, ctx: ToolContext): Promise<ToolResult> {
      const brief = str(args, "brief").trim();
      try {
        const result = await generateDesignBrief({
          cfg: ctx.cfg,
          ollama: options.ollama,
          brief,
          language: str(args, "language"),
          direction: normalizeDirection(str(args, "direction")),
          audience: str(args, "audience"),
          mood: str(args, "mood"),
          constraints: str(args, "constraints"),
          signal: ctx.signal,
          maxAttempts: num(args, "maxAttempts", 2),
        });

        // The generator already validates; re-check defensively so the tool can
        // never emit a brief that violates the palette/font contract.
        const check = normalizeDesignBrief(JSON.parse(JSON.stringify(result.brief)) as unknown, brief, result.brief.rtl);
        if (!check.ok) {
          return { ok: false, content: `design_brief produced an invalid brief: ${check.errors.join("; ")}` };
        }
        if (result.brief.palette.length < DESIGN_BRIEF_MIN_COLORS || result.brief.palette.length > DESIGN_BRIEF_MAX_COLORS) {
          return { ok: false, content: `design_brief palette must contain ${DESIGN_BRIEF_MIN_COLORS}-${DESIGN_BRIEF_MAX_COLORS} colours` };
        }
        if (result.brief.fonts.length > DESIGN_BRIEF_MAX_FONTS) {
          return { ok: false, content: `design_brief must use at most ${DESIGN_BRIEF_MAX_FONTS} font families` };
        }

        let tokensPath: string | undefined;
        if (bool(args, "writeTokens", false)) {
          const relPath = str(args, "tokensPath") || DESIGN_TOKENS_DEFAULT_PATH;
          try {
            tokensPath = await writeDesignTokens(ctx.workspace, relPath, result.brief);
          } catch (error) {
            return {
              ok: false,
              content: `design_brief wrote the brief but failed to persist tokens at ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
            };
          }
        }

        return {
          ok: true,
          content: formatDesignBriefResult(
            result.brief,
            { source: result.source, model: result.model, warnings: result.warnings },
            tokensPath,
          ),
        };
      } catch (error) {
        return { ok: false, content: `design_brief failed: ${error instanceof Error ? error.message : String(error)}` };
      }
    },
  }];
}
